import{_ as a,c as i,ag as s,o as l}from"./chunks/framework.kMCHP7uL.js";const k=JSON.parse('{"title":"0.13.0","description":"","frontmatter":{"outline":"deep","comments":false,"showVersion":false},"headers":[],"relativePath":"update/0.13.0-description.md","filePath":"update/0.13.0-description.md"}'),o={name:"update/0.13.0-description.md"};function t(c,e,d,n,r,h){return l(),i("div",null,e[0]||(e[0]=[s('<h1 id="_0-13-0" tabindex="-1"><code>0.13.0</code> <a class="header-anchor" href="#_0-13-0" aria-label="Permalink to &quot;`0.13.0`&quot;">​</a></h1><p>2024/6/7，<code>0.13.0</code> 發佈，歷時不足 2 個月，有 73 位貢獻者，一共進行了 415 次提交！</p><p>本次發佈週期相對其他版本較短，主要是對工具鏈進行升級，如升級至 <a href="https://ziglang.org/download/0.13.0/release-notes.html#LLVM-18" target="_blank" rel="noreferrer">LLVM 18</a>。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>有關於各平臺和架構的支持情況，本次更新並未進行更改，故在此處不再提及！</p></div><h2 id="構建系統" tabindex="-1">構建系統 <a class="header-anchor" href="#構建系統" aria-label="Permalink to &quot;構建系統&quot;">​</a></h2><h3 id="step-run-child-繼承-stderr-時獲得全局鎖" tabindex="-1"><code>Step.Run</code>：<code>child</code> 繼承 <code>stderr</code> 時獲得全局鎖 <a class="header-anchor" href="#step-run-child-繼承-stderr-時獲得全局鎖" aria-label="Permalink to &quot;`Step.Run`：`child` 繼承 `stderr` 時獲得全局鎖&quot;">​</a></h3><p>設置 <code>stdio</code> 為 <code>inherit</code> 的文檔：</p><blockquote><p>運行步驟被認為具有副作用，因此當它出現在構建圖中時總是會執行。</p><p>這也意味著這個步驟將獲得全局鎖，以防止其他步驟在此期間運行。</p><p>如果子進程崩潰或返回非零退出代碼，步驟將失敗。</p></blockquote><p>過去缺少該鎖的實現，現已添加，以確保 stdout/stderr 只會被一個進程佔用。</p><h3 id="默認情況下將-windows-dll-安裝到-prefix-bin" tabindex="-1">默認情況下將 Windows DLL 安裝到 <code>&lt;prefix&gt;/bin/</code> <a class="header-anchor" href="#默認情況下將-windows-dll-安裝到-prefix-bin" aria-label="Permalink to &quot;默認情況下將 Windows DLL 安裝到 `&lt;prefix&gt;/bin/`&quot;">​</a></h3><p>Windows 不支持 <code>RPATH</code>，默認情況下僅在少量預定路徑中搜索 DLL，其中之一是應用程序加載的目錄。</p><p>目前，如果您構建一個可執行文件和一個 DLL，鏈接它們並使用默認配置來安裝它們，exe 將進入 <code>bin/</code> ，DLL 將進入 <code>lib/</code> ，這導致在不手動將 <code>lib/</code> 添加到 <code>PATH</code> 環境變量中的前提下，exe 無法在運行時找到 DLL。</p><p>默認情況下將可執行文件和 DLL 安裝到 <code>bin/</code> 確保可執行文件能夠找到它鏈接到的 DLL。DLL 導入庫仍然安裝到 <code>lib/</code> 。</p><blockquote><p>目前該行為與 <a href="https://github.com/ziglang/zig/pull/19743" target="_blank" rel="noreferrer">CMake</a> 相同</p></blockquote><div class="important custom-block github-alert"><p class="custom-block-title">示例</p><p></p><div class="language-zig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">zig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">root_module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">linkLibrary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">sdl3_lib</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">installArtifact</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">installArtifact</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">sdl3_lib</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>構建結果：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zig-out/</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">├───bin/</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">│</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   ├───example.exe</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">│</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   ├───example.pdb</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">│</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   ├───SDL3.dll</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">│</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   └───SDL3.pdb</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">├───include/</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">│</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   └───SDL3/</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">│</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       ├───SDL.h</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">│</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       └───</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">omitte</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">└───lib/</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   └───SDL3.lib</span></span></code></pre></div></div><h3 id="step-objcopy-不接受多個-section" tabindex="-1"><code>Step.ObjCopy</code>：不接受多個 <code>section</code> <a class="header-anchor" href="#step-objcopy-不接受多個-section" aria-label="Permalink to &quot;`Step.ObjCopy`：不接受多個 `section`&quot;">​</a></h3><p>現在 <code>zig objcopy</code> 不接受保留多個 <code>section</code>，如果您將多個 <code>-j</code> <code>.section</code> 參數傳遞給 <code>zig objcopy</code>，它只會尊重最後傳遞的一個。</p><h2 id="編譯器" tabindex="-1">編譯器 <a class="header-anchor" href="#編譯器" aria-label="Permalink to &quot;編譯器&quot;">​</a></h2><h2 id="將-yes-color-環境變量替換為-clicolor-force" tabindex="-1">將 <code>YES_COLOR</code> 環境變量替換為 <code>CLICOLOR_FORCE</code> <a class="header-anchor" href="#將-yes-color-環境變量替換為-clicolor-force" aria-label="Permalink to &quot;將 `YES_COLOR` 環境變量替換為 `CLICOLOR_FORCE`&quot;">​</a></h2><p>檢測 <a href="https://no-color.org/" target="_blank" rel="noreferrer"><code>NO_COLOR</code></a> 環境變量並在其設置時禁用顏色輸出是大多數 CLI 工具所遵循的標準做法。</p><p>當涉及到即使不寫入終端時也強制輸出顏色的任務時，存在兩個標準：<code>CLICOLOR_FORCE</code> 和 <code>FORCE_COLOR</code>。這兩個標準都沒有像 <code>NO_COLOR</code> 那樣普遍存在，但它們都有一定的優先級，並且受到一部分 CLI 工具的尊重。</p><p>在 <a href="https://github.com/ziglang/zig/commit/e45d24c0de29eb6668e56ea927e15505674833a6" target="_blank" rel="noreferrer"><code>e45d24c</code></a> 之前，Zig 使用 ZIG_DEBUG_COLOR 環境變量強制顏色輸出，但該提交將其更改為 YES_COLOR。</p><p><code>YES_COLOR</code> 似乎目前在軟件中幾乎沒有先例（<a href="https://github.com/search?q=%2F%28%3F-i%29%5CbYES_COLOR%5Cb%2F&amp;type=code" target="_blank" rel="noreferrer">在 GitHub 上搜索 <code>/(?-i)\\bYES_COLOR\\b/</code> 返回了 142 個文件</a>）。</p><p>與其在混合中加入第三個標準並使用戶更難在 CLI 工具中管理彩色輸出，不如使用 <code>CLICOLOR_FORCE</code> 或 <code>FORCE_COLOR</code> 之一進行標記更有意義。</p><p>選擇 <code>CLICOLOR_FORCE</code> 而不是 <code>FORCE_COLOR</code> 的原因如下：</p><ul><li><a href="https://bixense.com/clicolors/" target="_blank" rel="noreferrer">https://bixense.com/clicolors/</a> 嘗試標準化 <code>CLICOLOR_FORCE</code>，創建於 2015 年。<code>FORCE_COLOR</code> 對應的 <a href="https://force-color.org/" target="_blank" rel="noreferrer">https://force-color.org/</a> 創建於 2023 年。</li><li><code>CLICOLOR_FORCE</code> 似乎是由 <code>ls</code> 於 2000 年在 FreeBSD <code>4.1.1</code> 中引入的。<code>FORCE_COLOR</code> 似乎是由 chalk JavaScript 庫於 2015 年引入的。</li><li><code>CLICOLOR_FORCE</code> 受 CMake 和 Ninja 支持。</li><li>雖然搜索 <code>/(?-i)\\bCLICOLOR_FORCE\\b/</code> 返回 28.9k 文件且搜索 <code>/(?-i)\\bFORCE_COLOR\\b/</code> 返回 39k 文件，但前者似乎在用 C/C++ 編寫的軟件中更常見，而後者似乎更常見於 Node.js 和 Python 相關生態系統。</li></ul><p><code>CLICOLOR_FORCE</code> 也會添加到 <code>zig env</code> 的輸出中。</p><h2 id="llvm-backend-後端" tabindex="-1"><code>LLVM Backend</code> 後端 <a class="header-anchor" href="#llvm-backend-後端" aria-label="Permalink to &quot;`LLVM Backend` 後端&quot;">​</a></h2><p>添加了 <code>loongarch64</code> 支持。它仍然無法構建 hello world，因為 LLVM 尚未為該目標實現 <code>fp_to_fp16</code>。</p><h3 id="zig-cache-重命名為-zig-cache" tabindex="-1"><code>zig-cache</code> 重命名為 <code>.zig-cache</code> <a class="header-anchor" href="#zig-cache-重命名為-zig-cache" aria-label="Permalink to &quot;`zig-cache` 重命名為 `.zig-cache`&quot;">​</a></h3><p>這與更多工具配合得很好。例如，文本編輯器通常會從“在文件中查找”功能中排除該目錄。</p><h2 id="bug-修復" tabindex="-1">Bug 修復 <a class="header-anchor" href="#bug-修復" aria-label="Permalink to &quot;Bug 修復&quot;">​</a></h2><p>在此發佈週期內解決的 43 個錯誤報告的<a href="https://github.com/ziglang/zig/issues?q=is%3Aclosed+is%3Aissue+label%3Abug+milestone%3A0.13.0" target="_blank" rel="noreferrer">完整列表</a>。</p><p>在這個發佈週期中引入並解決了許多錯誤，為了簡潔起見，這些發行說明中省略了大多數錯誤修復。</p><h2 id="當前版本包含的-bugs" tabindex="-1">當前版本包含的 Bugs <a class="header-anchor" href="#當前版本包含的-bugs" aria-label="Permalink to &quot;當前版本包含的 Bugs&quot;">​</a></h2><p>Zig 目前存在一些 <a href="https://github.com/ziglang/zig/issues?q=is%3Aopen+is%3Aissue+label%3Abug" target="_blank" rel="noreferrer">已知的 bugs</a>，甚至包含一些 <a href="https://github.com/ziglang/zig/issues?q=is%3Aopen+is%3Aissue+label%3Amiscompilation" target="_blank" rel="noreferrer">編譯錯誤</a>！</p><p>Zig 目前仍不成熟，即使是使用 <code>0.13.0</code> 也可能需要參與 zig 開發才能使之順利在某些項目開發上正常工作！</p><p>當 Zig 達到 <code>1.0.0</code> 時，<a href="https://ziglang.org/download/0.12.0/release-notes.html#Tier-1-Support" target="_blank" rel="noreferrer">一級支持</a> 將獲得一個額外的錯誤策略作為要求。</p><h2 id="工具鏈" tabindex="-1">工具鏈 <a class="header-anchor" href="#工具鏈" aria-label="Permalink to &quot;工具鏈&quot;">​</a></h2><h3 id="llvm-18" tabindex="-1">LLVM 18 <a class="header-anchor" href="#llvm-18" aria-label="Permalink to &quot;LLVM 18&quot;">​</a></h3><p>升級 LLVM 至 <a href="http://releases.llvm.org/16.0.0/docs/ReleaseNotes.html" target="_blank" rel="noreferrer"><code>18.1.7</code></a>，這是本次 <code>0.13.0</code> 發版的主要目的！</p><h3 id="musl-1-2-5" tabindex="-1">musl 1.2.5 <a class="header-anchor" href="#musl-1-2-5" aria-label="Permalink to &quot;musl 1.2.5&quot;">​</a></h3><p>Zig 附帶了 <code>musl</code> 的源代碼。當選擇 <code>musl C ABI</code> 時，Zig 會從源為所選目標構建靜態 <code>musl</code>。</p><p>Zig 還支持定位動態鏈接的 <code>musl</code>，這對於使用它作為系統 <code>libc</code> 的 Linux 發行版非常有用，例如 <code>Alpine Linux</code>。</p><p>從 <code>v1.2.4</code> 升級至 <code>v1.2.5</code>。</p><h3 id="glibc-2-39" tabindex="-1">glibc 2.39 <a class="header-anchor" href="#glibc-2-39" aria-label="Permalink to &quot;glibc 2.39&quot;">​</a></h3><p>交叉編譯時現在可以使用 <code>glibc</code> 版本 <code>2.39</code>。</p><h2 id="路線圖" tabindex="-1">路線圖 <a class="header-anchor" href="#路線圖" aria-label="Permalink to &quot;路線圖&quot;">​</a></h2><p><code>0.14.0</code> 發佈週期的主題將是編譯速度。</p><p>將在 <code>0.14.0</code> 發佈週期中努力實現一些即將到來的里程碑：</p><ul><li>使 <code>x86</code> 後端成為調試模式的默認後端。</li><li><code>COFF</code> 的鏈接器支持。消除對 <a href="https://lld.llvm.org/" target="_blank" rel="noreferrer"><code>LLD</code></a> 的依賴。</li><li>啟用增量編譯以實現快速重建。</li><li>將併發引入語義分析，進一步提高編譯速度。</li></ul><p>目前的思路是，優先考慮更快的編譯將提高編譯器本身的開發速度，從而在接下來的發佈週期中修復更多的錯誤並完成更多的功能。</p><blockquote><p>加快編譯速度也可能會對語言本身做出一些調整。</p></blockquote>',53)]))}const g=a(o,[["render",t]]);export{k as __pageData,g as default};
